def _find_eocd(data):
    """Scan backwards for the last EOCD signature pointing at a valid CD.

    A candidate must fit inside the buffer and its central-directory
    offset/size must land within the file before it. Scanning from the end
    means a real EOCD followed by a long comment wins over any decoy
    signatures embedded inside that comment.
    """
    lo = max(0, len(data) - (_EOCD_SIZE + _MAX_COMMENT))
    needle = struct.pack("<I", EOCD_SIG)
    pos = data.rfind(needle)
    while pos >= lo:
        if pos + _EOCD_SIZE <= len(data):
            try:
                n_total, cd_size, cd_offset = _parse_eocd(data, pos)
            except ZipError:
                n_total, cd_size, cd_offset = None, None, None
            if n_total is not None and cd_offset + cd_size <= pos:
                return pos
        pos = data.rfind(needle, lo, pos)
    raise ZipError("End of Central Directory record not found")
